"""
Detect / install Demucs for Advanced film audio enhance (vocal separation).

When an NVIDIA GPU is present, also upgrade to CUDA-enabled PyTorch
(from the official cu124 wheel index) so Demucs can run on GPU.
"""

from __future__ import annotations

import json
import os
import logging
import subprocess
import sys
import time
from pathlib import Path
from typing import Any, Callable
from urllib.parse import urlparse

ProgressCb = Callable[[dict[str, Any]], None]
_log = logging.getLogger("transub_engine.runtime_audio")

DEMUCS_PIP_PACKAGES = ("demucs",)

# Demucs GPU needs CUDA-enabled torch wheels (not the CPU build demucs often pulls).
# cu126: RTX 20–40 / Hopper (sm_50–sm_90); Aliyun hosts flat .whl mirrors.
# cu128: Blackwell RTX 50xx (sm_120) on CUDA 12.x drivers.
# cu130: Blackwell + CUDA 13+ drivers (also matches onnxruntime-gpu 1.27+ stack).
TORCH_CUDA_PACKAGES = ("torch", "torchaudio")
_PENDING_TORCH_CUDA_MARKER = "pending-torch-cuda-install.json"


def _torch_cuda_runtime_lists() -> dict[str, tuple[str, ...]]:
    from .pip_mirror_util import resolve_torch_cuda_variant_config

    cfg = resolve_torch_cuda_variant_config()
    return {
        "find_links": tuple(cfg.get("find_links") or ()),
        "index_urls": tuple(cfg.get("index_urls") or ()),
        "label": str(cfg.get("label") or "cu126"),
    }


def _torch_cuda_find_links() -> tuple[str, ...]:
    return _torch_cuda_runtime_lists()["find_links"]


def _torch_cuda_index_urls() -> tuple[str, ...]:
    return _torch_cuda_runtime_lists()["index_urls"]


def _torch_native_live_in_process() -> bool:
    """True when this process already mapped torch native libs (unsafe to overwrite)."""
    try:
        from .device import is_torch_c_extension_loaded, is_torch_fully_imported

        return bool(is_torch_fully_imported() or is_torch_c_extension_loaded())
    except Exception:
        return "torch" in sys.modules or "torch._C" in sys.modules


def _pending_torch_cuda_marker_path() -> Path:
    from .pip_mirror_util import wheel_cache_dir

    return wheel_cache_dir() / _PENDING_TORCH_CUDA_MARKER


def mark_pending_torch_cuda_install(
    wheel_paths: list[str],
    *,
    variant: str = "",
    source: str = "",
) -> Path:
    """Record CUDA torch wheels to install on the next cold engine start."""
    paths = [str(p) for p in wheel_paths if str(p).strip() and Path(str(p)).is_file()]
    marker = _pending_torch_cuda_marker_path()
    payload = {
        "wheelPaths": paths,
        "variant": str(variant or ""),
        "source": str(source or ""),
        "createdAt": time.time(),
    }
    marker.parent.mkdir(parents=True, exist_ok=True)
    marker.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    _log.info(
        "deferred CUDA torch install (%d wheels, variant=%s) → %s",
        len(paths),
        variant or "?",
        marker,
    )
    return marker


def clear_pending_torch_cuda_install() -> None:
    marker = _pending_torch_cuda_marker_path()
    try:
        if marker.is_file():
            marker.unlink()
    except OSError as err:
        _log.warning("clear pending torch cuda marker: %s", err)


def list_cached_torch_cuda_wheels(*, variant: str = "") -> list[str]:
    """Prefer matching +cu* wheels from the local wheel cache."""
    from .pip_mirror_util import wheel_cache_dir

    label = str(variant or _torch_cuda_runtime_lists()["label"] or "cu126").lower()
    needle = f"+{label}"
    cache = wheel_cache_dir()
    if not cache.is_dir():
        return []
    torch_paths: list[str] = []
    audio_paths: list[str] = []
    for name in sorted(os.listdir(cache)):
        low = name.lower()
        if not low.endswith(".whl") or needle not in low:
            continue
        full = str(cache / name)
        if low.startswith("torch-"):
            torch_paths.append(full)
        elif low.startswith("torchaudio-"):
            audio_paths.append(full)
    # Newest last path wins for each package if multiples exist.
    out: list[str] = []
    if torch_paths:
        out.append(torch_paths[-1])
    if audio_paths:
        out.append(audio_paths[-1])
    return out


def apply_pending_torch_cuda_install(
    *,
    on_progress: ProgressCb | None = None,
    force_from_cache: bool = False,
) -> dict[str, Any]:
    """Cold-install CUDA torch from the pending marker / wheel cache.

    Must run before ``import torch`` in this process. Used by ``serve`` startup
    after Demucs ensure deferred a live-process reinstall.
    """
    if _torch_native_live_in_process():
        return {
            "ok": False,
            "skipped": True,
            "code": "TORCH_CUDA_LIVE",
            "message": "本进程已加载 Torch，无法冷安装 CUDA 轮子",
        }

    marker = _pending_torch_cuda_marker_path()
    paths: list[str] = []
    variant = ""
    source = "pending-marker"
    if marker.is_file():
        try:
            data = json.loads(marker.read_text(encoding="utf-8"))
        except Exception as err:
            _log.warning("read pending torch cuda marker: %s", err)
            data = {}
        if isinstance(data, dict):
            variant = str(data.get("variant") or "")
            source = str(data.get("source") or source)
            raw = data.get("wheelPaths") or []
            if isinstance(raw, list):
                paths = [str(p) for p in raw if Path(str(p)).is_file()]
    if not paths and force_from_cache:
        paths = list_cached_torch_cuda_wheels(variant=variant)
        source = "wheel-cache"
    if not paths:
        if marker.is_file():
            clear_pending_torch_cuda_install()
        return {
            "ok": False,
            "skipped": True,
            "code": "TORCH_CUDA_PENDING_EMPTY",
            "message": "没有待安装的 CUDA torch 轮子",
        }

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    emit(
        {
            "type": "progress",
            "stage": "torch_cuda",
            "detail": f"正在冷安装 CUDA PyTorch（{variant or 'cu*'}，{len(paths)} 个轮子）…",
        }
    )
    try:
        from .pip_mirror_util import install_local_wheel_files
    except Exception as err:
        return {
            "ok": False,
            "code": "TORCH_CUDA_INSTALL_FAILED",
            "message": f"无法加载本地轮子安装器：{err}",
        }

    inst = install_local_wheel_files(
        paths,
        on_progress=on_progress,
        detail_prefix="CUDA PyTorch（冷安装）",
        timeout_sec=1800.0,
    )
    if not inst.get("ok"):
        return {
            "ok": False,
            "code": "TORCH_CUDA_INSTALL_FAILED",
            "message": str(inst.get("error") or "冷安装 CUDA torch 失败"),
            "stderr": str(inst.get("error") or ""),
        }
    clear_pending_torch_cuda_install()
    return {
        "ok": True,
        "installed": list(TORCH_CUDA_PACKAGES),
        "source": source,
        "wheelPaths": paths,
        "message": "已冷安装 CUDA PyTorch",
    }


def _probe_torch_cuda() -> dict[str, Any]:
    """Filesystem-only CUDA-torch probe. Never import torch or init CUDA.

    Model-picker / capabilities / Demucs status used to ``import torch`` and
    call ``torch.cuda.is_available()`` in the engine process. That LoadLibrary
    of unsigned CUDA DLLs can freeze the whole PC when Smart App Control / WDAC
    scans them, or when the NVIDIA driver hangs during CUDA init.
    """
    from .device import read_torch_version, torch_cuda_libs_present, torch_package_dir

    torch_version = read_torch_version()
    present = bool(torch_version or torch_package_dir().is_dir())
    torch_cuda = bool(present and torch_cuda_libs_present())
    return {
        "torchCuda": torch_cuda,
        "torchCudaName": "",
        "torchVersion": torch_version,
        "torchError": "",
        "torchPresent": present,
    }


def _has_nvidia_gpu() -> bool:
    try:
        from .device import detect_device

        return bool(detect_device().get("hasCuda"))
    except Exception:
        return False


def _demucs_pip_command() -> str:
    from .runtime_extras import ALIYUN_PIP

    index, host = ALIYUN_PIP
    return (
        f"python -m pip install --upgrade -i {index} --trusted-host {host} demucs"
    )


def _torch_cuda_pip_command(index_url: str | None = None) -> str:
    pkgs = " ".join(TORCH_CUDA_PACKAGES)
    if index_url:
        return (
            f"python -m pip install --upgrade --force-reinstall {pkgs} --index-url {index_url}"
        )
    lists = _torch_cuda_runtime_lists()
    label = lists["label"]
    links = lists["find_links"][0] if lists["find_links"] else (
        "https://download.pytorch.org/whl/cu130"
        if label.startswith("cu13")
        else "https://download.pytorch.org/whl/cu128"
    )
    # force-reinstall: CPU builds share the same X.Y.Z as CUDA wheels; upgrade alone skips.
    return (
        f"python -m pip install --upgrade --force-reinstall {pkgs} "
        f"--find-links {links} --no-index"
        + (
            f"  # {label}: Blackwell + CUDA 13 驱动请用 --index-url https://download.pytorch.org/whl/cu130"
            if label.startswith("cu13")
            else (
                f"  # {label}: Blackwell 请用 --index-url https://download.pytorch.org/whl/cu128"
                if label == "cu128"
                else ""
            )
        )
    )


def probe_audio_separate() -> dict[str, Any]:
    """Summarize Demucs / vocal-separation readiness (incl. PyTorch CUDA).

    Uses package metadata + DLL presence only. Importing demucs/torch here
    would load CUDA into the engine process and can freeze Windows.
    """
    from importlib.metadata import PackageNotFoundError, version as pkg_version

    from .device import detect_device, torch_cuda_variant_mismatch

    torch_info = _probe_torch_cuda()
    torch_cuda = bool(torch_info.get("torchCuda"))
    torch_present = bool(torch_info.get("torchPresent"))
    torch_error = str(torch_info.get("torchError") or "").strip()
    cuda_lists = _torch_cuda_runtime_lists()
    torch_variant = cuda_lists["label"]
    try:
        from .rocm_device import torch_rocm_libs_present

        torch_rocm = bool(torch_rocm_libs_present())
    except Exception:
        torch_rocm = False
    try:
        dev = detect_device()
        has_nvidia = bool(dev.get("hasCuda"))
        has_amd = bool(dev.get("hasRocm"))
        has_gpu = has_nvidia or has_amd
        gpu_name = str(dev.get("gpuName") or "").strip()
        torch_variant = str(dev.get("torchCudaVariant") or torch_variant)
    except Exception:
        has_nvidia = _has_nvidia_gpu()
        has_amd = False
        has_gpu = has_nvidia
        gpu_name = ""
    torch_cuda_name = gpu_name if torch_cuda else ""
    torch_mismatch = bool(has_nvidia and torch_cuda_variant_mismatch())
    need_rocm_torch = bool(has_amd and not torch_rocm)

    try:
        version = str(pkg_version("demucs") or "").strip() or "unknown"
    except PackageNotFoundError:
        version = ""
    except Exception:
        version = ""

    base = {
        "ok": True,
        "package": "demucs",
        "hasCudaGpu": has_nvidia,
        "hasRocm": has_amd,
        "torchCuda": torch_cuda,
        "torchRocm": torch_rocm,
        "torchCudaName": torch_cuda_name,
        "torchVersion": torch_info.get("torchVersion") or "",
        "torchError": torch_error,
        "packages": list(DEMUCS_PIP_PACKAGES),
        "torchCudaPackages": list(TORCH_CUDA_PACKAGES),
        "torchCudaVariant": torch_variant,
        "torchCudaMismatch": torch_mismatch,
        "pipCommand": _demucs_pip_command(),
        "torchCudaPipCommand": _torch_cuda_pip_command(),
    }

    if not version:
        return {
            **base,
            "status": "need_install",
            "installed": False,
            "version": "",
            "hint": (
                "未安装 Demucs。请在设置中「下载 Demucs（人声分离）」"
                + ("（AMD 会装 ROCm PyTorch）" if has_amd else "（有 NVIDIA 时会同时安装 CUDA 版 PyTorch）")
                + "。"
            ),
        }

    if torch_error:
        status = "need_torch_cuda"
        hint = (
            f"Demucs 已安装（{version}），但无法加载 PyTorch。"
            f"{torch_error}"
        )
    elif not torch_present:
        status = "need_torch_rocm" if has_amd else "need_torch_cuda"
        hint = (
            f"Demucs 已安装（{version}），但未找到 PyTorch。"
            + (
                "请点「自动修复」补齐 ROCm PyTorch。"
                if has_amd
                else (
                    "请重新「下载 Demucs」/「补齐 CUDA PyTorch」，或手动执行："
                    f" {_torch_cuda_pip_command()}"
                )
            )
        )
    elif need_rocm_torch:
        status = "need_torch_rocm"
        hint = (
            f"Demucs 已安装（{version}），但引擎缺少 ROCm PyTorch。"
            "请点「自动修复」装进引擎运行时（系统 pip 无效）。"
        )
    elif has_nvidia and not torch_cuda:
        status = "need_torch_cuda"
        hint = (
            f"Demucs 已安装（{version}），但引擎 PyTorch 无 CUDA。"
            "请重新「下载 Demucs」/「补齐 CUDA PyTorch」，或手动执行："
            f" {_torch_cuda_pip_command()}"
        )
    elif torch_mismatch:
        from .device import installed_torch_cuda_tag

        have = installed_torch_cuda_tag() or "cu126"
        status = "need_torch_cuda"
        hint = (
            f"Demucs 已安装（{version}），但 PyTorch 为 {have}，"
            f"本机 {gpu_name or 'Blackwell GPU'} 需要 {torch_variant}（CUDA 12.8+ 或 13.x）。"
            "请在设置中重新「补齐 CUDA PyTorch」或手动下载匹配版本的 torch / torchaudio。"
        )
    elif torch_cuda:
        status = "ready"
        hint = (
            f"Demucs 已安装（{version}），GPU 可用"
            + (f"：{torch_cuda_name}" if torch_cuda_name else "")
        )
    else:
        status = "ready"
        hint = (
            f"Demucs 已安装（{version}）；未检测到 NVIDIA GPU，人声分离将使用 CPU"
        )
    return {
        **base,
        "status": status,
        "installed": True,
        "version": version,
        "hint": hint,
    }


def _run_pip(
    args: list[str],
    *,
    timeout: int = 3600,
) -> subprocess.CompletedProcess[str]:
    cmd = [sys.executable, "-m", "pip", *args]
    _log.info("ensure_audio_separate pip: %s", " ".join(cmd))
    return subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        timeout=timeout,
        check=False,
    )


def _install_demucs(*, force: bool = False) -> dict[str, Any]:
    from .runtime_extras import (
        is_mirror_http_deny,
        note_mirror_denied,
        resolve_pip_mirror_order,
    )

    mirrors, _probe_rows, _used_prefer = resolve_pip_mirror_order()
    last_err = ""
    tried: list[str] = []
    for index, host in mirrors:
        args = [
            "install",
            "--upgrade",
            "-i",
            index,
            "--trusted-host",
            host,
            *DEMUCS_PIP_PACKAGES,
        ]
        if force:
            args.insert(1, "--force-reinstall")
        tried.append(host)
        try:
            proc = _run_pip(args, timeout=3600)
        except subprocess.TimeoutExpired:
            last_err = f"安装 Demucs 超时（镜像 {host}）"
            continue
        if proc.returncode == 0:
            return {"ok": True, "installed": list(DEMUCS_PIP_PACKAGES), "mirror": host}
        err_tail = (proc.stderr or proc.stdout or "").strip()[-1200:]
        last_err = err_tail or f"exit {proc.returncode}"
        if is_mirror_http_deny(last_err):
            note_mirror_denied(host)
            _log.warning("demucs pip HTTP deny via %s, switching mirror", host)
        else:
            _log.warning("demucs pip failed via %s: %s", host, last_err[:300])

    tried_s = " → ".join(tried) if tried else "无"
    return {
        "ok": False,
        "code": "AUDIO_SEPARATE_INSTALL_FAILED",
        "message": f"Demucs 安装失败（已尝试镜像：{tried_s}）。{last_err}",
        "stderr": last_err,
        "mirrorsTried": tried,
    }


def _verify_torch_cuda_after_install(source: str) -> dict[str, Any] | None:
    """Return success dict if CUDA torch works, else None and leave a note in logs."""
    try:
        from .runtime_gpu import inject_nvidia_lib_path

        inject_nvidia_lib_path()
    except Exception as err:
        _log.warning("inject_nvidia_lib_path after torch cuda: %s", err)
    try:
        from .device import torch_cuda_variant_mismatch

        if torch_cuda_variant_mismatch():
            _log.warning(
                "installed via %s but torch CUDA tag mismatches Blackwell GPU",
                source,
            )
            return None
    except Exception:
        pass
    torch_info = _probe_torch_cuda()
    if torch_info.get("torchCuda"):
        return {
            "ok": True,
            "installed": list(TORCH_CUDA_PACKAGES),
            "indexUrl": source,
            "torchVersion": torch_info.get("torchVersion") or "",
            "torchCudaName": torch_info.get("torchCudaName") or "",
        }
    _log.warning(
        "installed via %s but torch.cuda.is_available() is False (version=%s)",
        source,
        torch_info.get("torchVersion") or "?",
    )
    return None


def _local_torch_cuda_wheels_dir() -> str:
    """Dev/packaged ``wheels-edition/cuda`` next to the engine runtime (optional)."""
    here = os.path.abspath(os.path.dirname(__file__))
    # .../runtime/Lib/site-packages/transub_engine -> engine root
    engine_root = os.path.abspath(os.path.join(here, "..", "..", "..", ".."))
    candidate = os.path.join(engine_root, "wheels-edition", "cuda")
    if os.path.isdir(candidate):
        return candidate
    return ""


def _install_torch_cuda(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """
    Replace CPU torch (often pulled by demucs / PyPI) with CUDA wheels.

    Always force-reinstall: a newer CPU build (e.g. 2.13.0+cpu) otherwise blocks
    older CUDA tags on cu124 (max 2.6), and same X.Y.Z+cu* may look "satisfied".

    Prefer local wheels-edition/cuda, then resumable direct .whl downloads, then
    Aliyun --find-links (hosts real .whl). PEP 503 indexes often redirect the
    download to download.pytorch.org which stalls in CN.
    """
    del force  # always force-reinstall CPU→CUDA; kept for call-site compatibility
    last_err = ""
    cuda_lists = _torch_cuda_runtime_lists()
    variant_label = cuda_lists["label"]
    find_links = _torch_cuda_find_links()
    index_urls = _torch_cuda_index_urls()
    variant_needle = f"+{variant_label}"

    def emit(payload: dict[str, Any]) -> None:
        if on_progress:
            try:
                on_progress(payload)
            except Exception:
                pass

    def _host_label(source: str) -> str:
        text = str(source or "").strip()
        if not text:
            return "未知源"
        if os.path.isdir(text):
            return "本地"
        try:
            host = (urlparse(text).hostname or "").strip()
            return host or text[:48]
        except Exception:
            return text[:48]

    def _try_local_wheel_paths(paths: list[str], source: str) -> dict[str, Any] | None:
        nonlocal last_err
        if not paths:
            return None
        try:
            from .pip_mirror_util import install_local_wheel_files
        except Exception:
            install_local_wheel_files = None  # type: ignore[assignment]
        host = _host_label(source)
        # Never overwrite site-packages while this process already mapped torch._C —
        # that poisons the live interpreter and often leaves a hybrid broken install.
        if _torch_native_live_in_process():
            mark_pending_torch_cuda_install(
                paths,
                variant=variant_label,
                source=source,
            )
            emit(
                {
                    "type": "progress",
                    "stage": "torch_cuda",
                    "detail": (
                        f"CUDA PyTorch 轮子已就绪（{variant_label}，{host}）；"
                        "引擎已加载 Torch，将在重启后冷安装…"
                    ),
                    "mirror": source,
                    "restartRequired": True,
                }
            )
            return {
                "ok": True,
                "deferred": True,
                "restartRequired": True,
                "code": "TORCH_CUDA_DEFERRED",
                "installed": [],
                "message": (
                    "已下载 CUDA PyTorch，将在引擎重启后冷安装"
                    "（避免进程内改装损坏 Torch）"
                ),
                "source": source,
                "torchCudaVariant": variant_label,
            }
        emit(
            {
                "type": "progress",
                "stage": "torch_cuda",
                "detail": (
                    f"正在安装 CUDA PyTorch（{variant_label}，{host}，解压写入中，约 2.5GB）…"
                ),
                "mirror": source,
            }
        )
        if install_local_wheel_files:
            inst = install_local_wheel_files(
                paths,
                on_progress=on_progress,
                detail_prefix="CUDA PyTorch",
                timeout_sec=1800.0,
            )
            if not inst.get("ok"):
                last_err = str(inst.get("error") or "local wheel install failed")
                return None
        else:
            cmd = [
                sys.executable,
                "-u",
                "-m",
                "pip",
                "install",
                "--force-reinstall",
                "--no-deps",
                "--no-index",
                "--no-cache-dir",
                *paths,
            ]
            try:
                proc = subprocess.run(
                    cmd,
                    capture_output=True,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    timeout=1800,
                    check=False,
                )
            except subprocess.TimeoutExpired:
                last_err = f"timeout installing local wheels via {source}"
                return None
            if proc.returncode != 0:
                last_err = (proc.stderr or proc.stdout or "").strip()[-1200:]
                return None
        return _verify_torch_cuda_after_install(source)

    # 1) Packaged / dev wheels-edition/cuda beside the engine.
    local_cuda = _local_torch_cuda_wheels_dir()
    if local_cuda:
        local_paths = [
            os.path.join(local_cuda, name)
            for name in os.listdir(local_cuda)
            if name.endswith(".whl")
            and variant_needle in name.lower()
            and (
                name.lower().startswith("torch-")
                or name.lower().startswith("torchaudio-")
            )
        ]
        local_paths.sort()
        ok = _try_local_wheel_paths(local_paths, local_cuda)
        if ok:
            return ok

    # 2) Resumable direct downloads (progress + ~60s stall detection).
    try:
        from .pip_mirror_util import download_torch_cuda_wheels
    except Exception:
        download_torch_cuda_wheels = None  # type: ignore[assignment]
    if download_torch_cuda_wheels:
        dl = download_torch_cuda_wheels(
            on_progress=on_progress,
            detail_prefix="CUDA PyTorch",
        )
        if dl.get("ok"):
            ok = _try_local_wheel_paths(
                list(dl.get("localPaths") or []),
                str(dl.get("source") or dl.get("host") or "direct"),
            )
            if ok:
                return ok
            last_err = last_err or "installed direct wheels but CUDA libs missing"
        else:
            last_err = str(dl.get("error") or last_err or "direct download failed")

    # 3) pip --find-links / --index-url with live progress (not silent subprocess.run).
    try:
        from .runtime_extras import _run_pip_with_progress
    except Exception as err:
        return {
            "ok": False,
            "code": "TORCH_CUDA_INSTALL_FAILED",
            "message": f"无法加载 pip 安装器：{err}",
            "stderr": last_err,
        }

    attempts: list[tuple[str, list[str]]] = []
    for links in find_links:
        attempts.append(
            (
                links,
                [
                    "install",
                    "--upgrade",
                    "--force-reinstall",
                    *TORCH_CUDA_PACKAGES,
                    "--find-links",
                    links,
                    "--no-index",
                ],
            )
        )
    for index_url in index_urls:
        attempts.append(
            (
                index_url,
                [
                    "install",
                    "--upgrade",
                    "--force-reinstall",
                    *TORCH_CUDA_PACKAGES,
                    "--index-url",
                    index_url,
                ],
            )
        )

    for source, args in attempts:
        if _torch_native_live_in_process():
            cached = list_cached_torch_cuda_wheels(variant=variant_label)
            if cached:
                marked = _try_local_wheel_paths(cached, "wheel-cache")
                if marked:
                    return marked
            return {
                "ok": False,
                "code": "TORCH_CUDA_LIVE",
                "restartRequired": True,
                "message": (
                    "引擎进程已加载 Torch，无法通过 pip 原地改装 CUDA。"
                    "请重启引擎后再点「补齐 CUDA PyTorch」。"
                ),
                "torchCudaVariant": variant_label,
                "stderr": last_err,
            }
        host = _host_label(source)
        emit(
            {
                "type": "progress",
                "stage": "torch_cuda",
                "detail": (
                    f"正在通过 pip 安装 CUDA PyTorch（{variant_label}，{host}，约 2.5GB）…"
                ),
                "mirror": source,
            }
        )
        try:
            proc = _run_pip_with_progress(
                args,
                on_progress=on_progress,
                label="CUDA PyTorch",
                host=host,
                timeout=3600,
            )
        except subprocess.TimeoutExpired:
            last_err = f"timeout via {source}"
            _log.warning("%s", last_err)
            continue
        if proc.returncode == 0:
            ok = _verify_torch_cuda_after_install(source)
            if ok:
                return ok
            last_err = (
                f"installed via {source} but torch.cuda.is_available() is False"
            )
            continue
        last_err = (proc.stderr or proc.stdout or "").strip()[-1200:]
        _log.warning("torch CUDA install failed via %s: %s", source, last_err[:200])

    return {
        "ok": False,
        "code": "TORCH_CUDA_INSTALL_FAILED",
        "message": (
            f"CUDA 版 PyTorch（{variant_label}）安装失败。可点「手动下载」获取 "
            f"{variant_label} 的 torch / torchaudio，或执行："
            f" {_torch_cuda_pip_command()}；详情：{last_err}"
        ),
        "stderr": last_err,
        "suggestManual": True,
        "manualKind": "torch-cuda",
        "torchCudaVariant": variant_label,
    }


def ensure_audio_separate(
    *,
    force: bool = False,
    on_progress: ProgressCb | None = None,
) -> dict[str, Any]:
    """Install Demucs (+ CUDA PyTorch when NVIDIA GPU is present)."""

    def progress(ev: dict[str, Any]) -> None:
        if on_progress:
            on_progress(ev)

    probe = probe_audio_separate()
    progress(
        {
            "type": "progress",
            "stage": "probe",
            "percent": 5,
            "detail": probe.get("hint") or "检测 Demucs…",
            "probe": probe,
        }
    )

    status = str(probe.get("status") or "")
    if status == "ready" and not force:
        return {
            "ok": True,
            "skipped": True,
            "reason": "already_ready",
            "probe": probe,
            "message": probe.get("hint"),
        }

    installed: list[str] = []
    need_demucs = force or status == "need_install" or not probe.get("installed")
    need_cuda_torch = force or status == "need_torch_cuda" or (
        bool(probe.get("hasCudaGpu")) and (
            not bool(probe.get("torchCuda"))
            or bool(probe.get("torchCudaMismatch"))
        )
    )
    need_rocm_torch = force or status == "need_torch_rocm" or (
        bool(probe.get("hasRocm")) and not bool(probe.get("torchRocm"))
    )

    if need_demucs:
        progress(
            {
                "type": "progress",
                "stage": "download",
                "percent": 12,
                "detail": "正在安装 Demucs（人声分离，含依赖，体积较大，请稍候）…",
                "packages": list(DEMUCS_PIP_PACKAGES),
            }
        )
        demucs_res = _install_demucs(force=force)
        if not demucs_res.get("ok"):
            return {
                **demucs_res,
                "probe": probe_audio_separate(),
            }
        installed.extend(demucs_res.get("installed") or [])
        # demucs often pulls CPU torch — always try accelerator torch next if GPU present
        need_cuda_torch = need_cuda_torch or _has_nvidia_gpu()
        try:
            from .rocm_device import amd_gpu_present

            need_rocm_torch = need_rocm_torch or amd_gpu_present()
        except Exception:
            pass

    torch_res: dict[str, Any] | None = None
    torch_variant_label = str(probe.get("torchCudaVariant") or _torch_cuda_runtime_lists()["label"])
    if need_rocm_torch and not _has_nvidia_gpu():
        progress(
            {
                "type": "progress",
                "stage": "torch_rocm",
                "percent": 48,
                "detail": "正在安装 ROCm 版 PyTorch（Demucs / AMD GPU）…",
            }
        )
        try:
            from .rocm_device import install_torch_rocm

            torch_res = install_torch_rocm(force=True, on_progress=progress)
        except Exception as err:
            torch_res = {
                "ok": False,
                "code": "TORCH_ROCM_INSTALL_FAILED",
                "message": str(err),
            }
        if not torch_res.get("ok"):
            return {
                **torch_res,
                "probe": probe_audio_separate(),
                "installed": installed,
            }
        installed.extend(torch_res.get("installed") or ["torch"])
    elif need_cuda_torch and _has_nvidia_gpu():
        progress(
            {
                "type": "progress",
                "stage": "torch_cuda",
                "percent": 48,
                "detail": (
                    f"正在安装 CUDA 版 PyTorch（{torch_variant_label}，Demucs GPU，约 2GB+，请稍候）…"
                ),
                "packages": list(TORCH_CUDA_PACKAGES),
                "indexUrls": list(_torch_cuda_index_urls()),
                "torchCudaVariant": torch_variant_label,
            }
        )
        torch_res = _install_torch_cuda(force=force, on_progress=progress)
        if torch_res.get("ok"):
            installed.extend(torch_res.get("installed") or [])
        else:
            # Demucs itself may be usable on CPU — report soft failure with guidance.
            after_partial = probe_audio_separate()
            if after_partial.get("installed"):
                progress(
                    {
                        "type": "progress",
                        "stage": "torch_cuda",
                        "percent": 88,
                        "detail": torch_res.get("message")
                        or "CUDA torch 安装失败，Demucs 仍可用（CPU）",
                        "restartRequired": bool(torch_res.get("restartRequired")),
                    }
                )
                soft: dict[str, Any] = {
                    "ok": True,
                    "skipped": False,
                    "partial": True,
                    "code": torch_res.get("code"),
                    "installed": installed,
                    "probe": after_partial,
                    "message": (
                        (after_partial.get("hint") or "Demucs 已安装")
                        + "；"
                        + str(torch_res.get("message") or "CUDA torch 未装上")
                    ),
                    "torchCuda": torch_res,
                }
                if torch_res.get("restartRequired") or torch_res.get("deferred"):
                    soft["restartRequired"] = True
                    soft["deferred"] = True
                return soft
            return {
                **torch_res,
                "installed": installed,
                "probe": after_partial,
            }
    elif need_torch and not _has_nvidia_gpu():
        progress(
            {
                "type": "progress",
                "stage": "torch_cuda",
                "percent": 70,
                "detail": "未检测到 NVIDIA GPU，跳过 CUDA 版 PyTorch",
            }
        )

    progress(
        {
            "type": "progress",
            "stage": "verify",
            "percent": 92,
            "detail": "正在校验 Demucs / PyTorch CUDA…",
        }
    )

    after = probe_audio_separate()
    if not after.get("installed"):
        return {
            "ok": False,
            "code": "AUDIO_SEPARATE_INSTALL_FAILED",
            "probe": after,
            "installed": installed,
            "message": after.get("hint") or "Demucs 安装后仍不可用",
        }

    partial = after.get("status") == "need_torch_cuda"
    detail = after.get("hint") or "Demucs 已就绪"
    deferred = bool(torch_res and (torch_res.get("deferred") or torch_res.get("restartRequired")))
    if deferred:
        detail = str(torch_res.get("message") or detail)
        partial = True
    progress(
        {
            "type": "done" if not partial else "progress",
            "stage": "done",
            "percent": 100,
            "detail": detail,
            "probe": after,
            "restartRequired": deferred,
        }
    )
    out: dict[str, Any] = {
        "ok": True,
        "skipped": False,
        "partial": partial,
        "installed": installed,
        "probe": after,
        "message": detail,
        "torchCuda": torch_res,
    }
    if deferred:
        out["deferred"] = True
        out["restartRequired"] = True
        out["code"] = str(torch_res.get("code") or "TORCH_CUDA_DEFERRED")
    return out
